sys_script_client.script:
function onSubmit() {

    /*
     * ============================================================
     * CARESYNC 360 - BED MASTER CLIENT VALIDATION
     * ============================================================
     *
     * Purpose:
     * Validate Bed data before INSERT or UPDATE.
     *
     * Returning false prevents the form from being submitted.
     * Therefore invalid records are NOT saved or updated.
     */


    /*
     * ------------------------------------------------------------
     * Read form values
     * ------------------------------------------------------------
     */

    var bedName = (g_form.getValue('bed_name') || '').trim();
    var ward = (g_form.getValue('ward') || '').trim();
    var department = (g_form.getValue('department') || '').trim();
    var location = (g_form.getValue('location') || '').trim();

    var bedStatus = (g_form.getValue('bed_status') || '').trim();
    var bedType = (g_form.getValue('bed_type') || '').trim();

    var floorValue = (g_form.getValue('floor') || '').trim();


    /*
     * ------------------------------------------------------------
     * 1. Bed Name validation
     * ------------------------------------------------------------
     */

    if (!bedName) {

        g_form.showFieldMsg(
            'bed_name',
            'Bed Name is required.',
            'error'
        );

        return false;
    }


    if (bedName.length < 2) {

        g_form.showFieldMsg(
            'bed_name',
            'Bed Name must contain at least 2 characters.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 2. Ward validation
     * ------------------------------------------------------------
     */

    if (!ward) {

        g_form.showFieldMsg(
            'ward',
            'Ward is required.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 3. Department validation
     * ------------------------------------------------------------
     */

    if (!department) {

        g_form.showFieldMsg(
            'department',
            'Department is required.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 4. Location validation
     * ------------------------------------------------------------
     */

    if (!location) {

        g_form.showFieldMsg(
            'location',
            'Location is required.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 5. Bed Status validation
     * ------------------------------------------------------------
     */

    if (!bedStatus) {

        g_form.showFieldMsg(
            'bed_status',
            'Please select a Bed Status.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 6. Bed Type validation
     * ------------------------------------------------------------
     */

    if (!bedType) {

        g_form.showFieldMsg(
            'bed_type',
            'Please select a Bed Type.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 7. Floor validation
     * ------------------------------------------------------------
     *
     * Floor is REQUIRED.
     *
     * It must:
     * - contain a value
     * - contain only digits
     * - be a whole number
     * - not be negative
     *
     * IMPORTANT:
     * Floor is an INTEGER field.
     *
     * We inspect the actual form control as well as g_form value
     * so alphabetic input such as "ABC" is rejected before the
     * record can be submitted.
     */

    var floorControl = g_form.getControl('floor');
    var rawFloorValue = floorControl ? floorControl.value.trim() : floorValue;


    if (!rawFloorValue) {

        g_form.showFieldMsg(
            'floor',
            'Floor is required.',
            'error'
        );

        return false;
    }


    if (!/^\d+$/.test(rawFloorValue)) {

        g_form.showFieldMsg(
            'floor',
            'Floor must be a whole number.',
            'error'
        );

        return false;
    }


    var floor = parseInt(rawFloorValue, 10);


    if (floor < 0) {

        g_form.showFieldMsg(
            'floor',
            'Floor cannot be negative.',
            'error'
        );

        return false;
    }


    /*
     * ------------------------------------------------------------
     * 8. Final validation result
     * ------------------------------------------------------------
     *
     * If execution reaches this point, all validations passed.
     *
     * Returning true allows:
     * - INSERT
     * - UPDATE
     */

    return true;
}
